export function inspectMilestoneBlock(input: { stateRoot: string; roots: MilestoneRootTuple }) { const block = currentBlock(readStore(input.stateRoot)); if (stable(block.roots) !== stable(input.roots)) throw new Error('milestone_root_mismatch'); const next = block.phase === 'active' ? 'pilot_evaluation_preflight' : ['closing_evaluation','terminal_unreported'].includes(block.phase) ? milestoneNextProducer(block) : ['closing_final', 'recording_pending'].includes(block.phase) ? 'recording_binding_inspect' : 'none'; return publicBlock(block, 'inspected', next); }
