export function updateMilestoneBlock<T>(stateRoot: string, blockId: string, callback: (block: DurableMilestoneBlock) => T): T { return withOwnerLock(stateRoot, () => { const store = readStore(stateRoot); const block = currentBlock(store); if (block.block_id !== blockId) throw new Error('milestone_block_assertion_mismatch'); const result = callback(block); block.revision = blockRevision(block); writeStore(stateRoot, store.blocks); return result; }); }
export function readMilestoneBlock(stateRoot: string, blockId: string): DurableMilestoneBlock { const matches = readStore(stateRoot).blocks.filter((block) => block.block_id === blockId); if (matches.length !== 1) throw new Error(matches.length ? 'milestone_block_ambiguous' : 'milestone_block_missing'); return structuredClone(matches[0]); }
export function inspectMilestoneBlockOwned<T>(stateRoot:string,blockId:string,callback:(block:DurableMilestoneBlock)=>T):T{return withOwnerLock(stateRoot,()=>{const matches=readStore(stateRoot).blocks.filter(block=>block.block_id===blockId);if(matches.length!==1)throw new Error(matches.length?'milestone_block_ambiguous':'milestone_block_missing');return callback(structuredClone(matches[0]))})}
export function findMilestoneLandingByRawIntent(stateRoot:string,rawProviderIntentId:string):{block:DurableMilestoneBlock;landing:DurableMilestoneLanding}|null{if(!/^[0-9a-f]{64}$/.test(rawProviderIntentId))throw new Error('milestone_landing_intent_invalid');const matches=readStore(stateRoot).blocks.flatMap(block=>(block.landings??[]).filter(landing=>landing.raw_provider_intent_id===rawProviderIntentId).map(landing=>({block,landing})));if(matches.length>1)throw new Error('milestone_landing_ambiguous');return matches.length?structuredClone(matches[0]):null}
export function findMilestoneLandingById(stateRoot:string,landingId:string):{block:DurableMilestoneBlock;landing:DurableMilestoneLanding}|null{if(!/^landing-[0-9a-f]{32}$/.test(landingId))throw new Error('milestone_landing_intent_invalid');const matches=readStore(stateRoot).blocks.flatMap(block=>(block.landings??[]).filter(landing=>landing.landing_id===landingId).map(landing=>({block,landing})));if(matches.length>1)throw new Error('milestone_landing_ambiguous');return matches.length?structuredClone(matches[0]):null}
export function inspectMilestoneLandingProjection(stateRoot:string,blockId:string){const block=readMilestoneBlock(stateRoot,blockId);return{schema:'ecpe.milestone-landing-projection.v1' as const,source_block_id:block.block_id,source_block_revision:block.revision,events:(block.landings??[]).flatMap(landing=>[{event:'recording.milestone_landing_intent' as const,sequence:landing.sequence,event_hash:landing.intent_event_hash,previous_event_hash:landing.previous_event_hash,landing_id:landing.landing_id,raw_provider_intent_id:landing.raw_provider_intent_id,ship_receipt_id:landing.ship_receipt_id,lanes:landing.lanes},...(landing.phase==='checkpointed'?[{event:'recording.milestone_checkpoint' as const,sequence:landing.sequence,event_hash:landing.checkpoint_event_hash!,previous_event_hash:landing.intent_event_hash,landing_id:landing.landing_id,merge_sha:landing.merge_sha!,delivery_receipt_id:landing.delivery_receipt_id!,delivery_receipt_binding_sha256:landing.delivery_receipt_binding_sha256!,landing_checkpoint_id:landing.landing_checkpoint_id!,landing_checkpoint_binding_sha256:landing.landing_checkpoint_binding_sha256!,release_drift_status:landing.release_drift_status!,provider_base_atomicity:'observed_only' as const,lanes:landing.lanes}]:[])])}}
export function findActiveMilestoneBlockForParticipant(input:{stateRoot:string;participant:typeof ECPE_PILOT_PARTICIPANTS[number];lane:typeof ECPE_PILOT_LANES[number]}):DurableMilestoneBlock|null{const matches=readStore(input.stateRoot).blocks.filter(block=>block.phase==='active'&&block.participants.includes(input.participant)&&block.lanes.includes(input.lane));if(matches.length>1)throw new Error('milestone_block_ambiguous');return matches.length===1?structuredClone(matches[0]):null}
export function findMilestoneBlockBySlot(stateRoot: string, slotId: string): DurableMilestoneBlock { const matches = readStore(stateRoot).blocks.filter((block) => block.slot?.slot_id === slotId); if (matches.length !== 1) throw new Error(matches.length ? 'evaluation_slot_ambiguous' : 'evaluation_slot_missing'); return structuredClone(matches[0]); }
export function claimHarnessVerificationProducer(input:{stateRoot:string;blockId:string;slotId:string;expectedBase:string;expectedHead:string}){
  if(!/^[0-9a-f]{40}$/.test(input.expectedBase)||!/^[0-9a-f]{40}$/.test(input.expectedHead))throw new Error('harness_checkpoint_subject_invalid');
  return withHarnessProducerGate(input.stateRoot,()=>updateMilestoneBlock(input.stateRoot,input.blockId,(block)=>{
    if(block.phase!=='closing_evaluation'||!block.slot||block.slot.slot_id!==input.slotId||block.terminal_reason)throw new Error('harness_checkpoint_phase_invalid');
    const position=block.slot.positions.find(item=>item.participant==='harness-governance');if(!position)throw new Error('participant_position_missing');
    const prerequisites=block.slot.positions.filter(item=>item.participant==='portfolioops'||item.participant==='cdo-os');if(prerequisites.length!==2||prerequisites.some(item=>item.state!=='attached'))throw new Error('harness_checkpoint_prerequisite_incomplete');
    const claimBody={block_id:block.block_id,slot_id:block.slot.slot_id,participant:'harness-governance',generation:0,descriptor_id:'harness.t4',expected_base_sha:input.expectedBase,expected_head_sha:input.expectedHead,subject_hash:block.slot.participant_subject_hashes['harness-governance'],roots:block.roots};
    const claimId=`claim-${digest(stable(claimBody)).slice(0,32)}`;
    if(position.state==='producer_reserved'){
      if(position.producer_claim_id!==claimId||position.generation!==0||position.origin_producer_claim_id!==claimId)throw new Error('harness_checkpoint_claim_conflict');
      return{result:'reused',claim_id:claimId,generation:position.generation,descriptor_id:position.descriptor_id,next_operation:'verification_workspace_prepare'};
    }
    if(position.state!=='empty')throw new Error('participant_proof_already_resolved');if(input.expectedHead!==block.code_root_head)throw new Error('harness_checkpoint_subject_moved');
    const recordedAt=new Date().toISOString();
    const eventCore={kind:'producer_claimed' as const,generation:0 as const,claim_id:claimId,parent_event_hash:null,ambiguity_sha256:null,recorded_at:recordedAt};
    position.state='producer_reserved';position.producer_claim_id=claimId;position.origin_producer_claim_id=claimId;position.generation=0;position.descriptor_id='harness.t4';position.expected_base_sha=input.expectedBase;position.expected_head_sha=input.expectedHead;position.resource_lineage_id=null;position.verification_resource_handle=null;position.replays_used=0;position.retry_started_at=null;position.retry_deadline_at=null;position.consumed_ambiguous_sha256=null;position.producer_events=[{...eventCore,event_hash:digest(`ecpe.harness-producer-event.v1\0${stable(eventCore)}`)}];
    return{result:'producer_claimed',claim_id:claimId,generation:0,descriptor_id:'harness.t4',next_operation:'verification_workspace_prepare'};
  }));
}
export function evaluateAndStopMilestoneSafety(input:{stateRoot:string;blockId:string;roots:MilestoneRootTuple;sources:Array<{source_id:string;status:'pass'|'not_applicable'|'unknown'|'regressed';status_hash:string}>;activations:Record<typeof ECPE_PILOT_LANES[number],{activation:'legacy'|'shadow'|'enforce';profile_lineage_hash:string}>;now?:Date}){return updateMilestoneBlock(input.stateRoot,input.blockId,block=>{if(stable(block.roots)!==stable(input.roots)||block.phase!=='active')throw new Error('milestone_safety_stop_invalid');if(input.sources.some(source=>!/^[0-9a-f]{64}$/.test(source.status_hash)))throw new Error('milestone_safety_source_invalid');const regressed=input.sources.filter(source=>source.status==='regressed');if(!regressed.length){return{result:input.sources.some(source=>source.status==='unknown')?'incomplete':'clear',block_id:block.block_id,phase:block.phase,next_operation:'pilot_evaluation_preflight'}}const stoppedAt=input.now??new Date();const receiptId=`stop-${digest(stable({block_id:block.block_id,reason:'safety_failure',sources:regressed.map(item=>[item.source_id,item.status_hash]).sort(),activations:input.activations})).slice(0,32)}`;block.phase='terminal_unreported';block.terminal_reason='safety_failure';block.terminal_kind=null;block.terminal_at=stoppedAt.toISOString();block.stop_receipt_id=receiptId;block.latches=ECPE_PILOT_LANES.filter(lane=>input.activations[lane].activation==='enforce').map(lane=>({latch_id:`latch-${digest(stable({receipt_id:receiptId,participant:'portfolioops',lane,lineage:input.activations[lane].profile_lineage_hash})).slice(0,32)}`,participant:'portfolioops',lane,profile_lineage_hash:input.activations[lane].profile_lineage_hash,execution:'legacy',stop_receipt_id:receiptId,superseded:false}));return{result:'stopped',block_id:block.block_id,phase:block.phase,terminal_reason:block.terminal_reason,stop_receipt_id:receiptId,latch_ids:block.latches.map(item=>item.latch_id),next_operation:'milestone_block_inspect_for_partial'}})}
type SafetyActivations=Record<typeof ECPE_PILOT_LANES[number],{activation:'legacy'|'shadow'|'enforce';profile_lineage_hash:string}>;
type CanaryPredecessors=Record<typeof ECPE_PILOT_LANES[number],{state_id:string|null;window_id:string|null;phase:string;revision:string|null}>;
export function recordCanarySafetyStop(input:{stateRoot:string;blockId:string;participant:'portfolioops';causeLane:typeof ECPE_PILOT_LANES[number];comparison:Record<string,unknown>&{comparison_id:string;source_block_id:string;focused_run_id:string;legacy_control_run_id:string;subject_head:string;subject_tree:string;policy_hash:string;class:'safety_regressed';ordinal:number};activations?:SafetyActivations;profileBlobSha?:string;canaryPredecessors?:CanaryPredecessors;resolveSnapshot?:()=>{activations:SafetyActivations;profileBlobSha:string;canaryPredecessors:CanaryPredecessors;release?:()=>void};now?:Date}){
  return withOwnerLock(input.stateRoot,()=>{
    const store=readStore(input.stateRoot);
    const matches=store.blocks.filter(item=>item.block_id===input.blockId);
    if(matches.length!==1)throw new Error('canary_safety_stop_invalid');
    const block=matches[0];
    if(input.participant!=='portfolioops'||!ECPE_PILOT_LANES.includes(input.causeLane)||input.comparison.source_block_id!==block.block_id||input.comparison.policy_hash!==block.policy_hash||input.comparison.class!=='safety_regressed'||!/^comparison-[0-9a-f]{32}$/.test(input.comparison.comparison_id)||!/^focused-[0-9a-f]{32}$/.test(input.comparison.focused_run_id)||!/^control-[0-9a-f]{32}$/.test(input.comparison.legacy_control_run_id)||![input.comparison.subject_head,input.comparison.subject_tree].every(value=>/^[0-9a-f]{40}$/.test(value)))throw new Error('canary_safety_stop_invalid');
    if(block.safety_stop_event){if(block.safety_stop_event.participant!==input.participant||block.safety_stop_event.cause_lane!==input.causeLane||stable(block.safety_stop_event.comparison)!==stable(input.comparison))throw new Error('canary_safety_stop_conflict');return{result:'reused' as const,block_id:block.block_id,phase:block.phase,terminal_reason:block.terminal_reason,stop_receipt_id:block.safety_stop_event.stop_receipt_id,latch_ids:block.latches.map(item=>item.latch_id)}}
    const resolved=input.resolveSnapshot?.();
    try{
    const activations=resolved?.activations??input.activations;
    const profileBlobSha=resolved?.profileBlobSha??input.profileBlobSha;
    const canaryPredecessors=resolved?.canaryPredecessors??input.canaryPredecessors??Object.fromEntries(ECPE_PILOT_LANES.map(lane=>[lane,{state_id:null,window_id:null,phase:'missing',revision:null}]))as CanaryPredecessors;
    if(!activations||!profileBlobSha||!/^[0-9a-f]{40,64}$/.test(profileBlobSha)||ECPE_PILOT_LANES.some(lane=>!activations[lane]||!/^[0-9a-f]{64}$/.test(activations[lane].profile_lineage_hash)||!canaryPredecessors[lane]))throw new Error('canary_safety_stop_invalid');
    const cause={participant:input.participant,cause_lane:input.causeLane,comparison:input.comparison,activations,profile_blob_sha:profileBlobSha,canary_predecessors:canaryPredecessors};
    const receiptId=`stop-${digest(stable({block_id:block.block_id,reason:'safety_failure',...cause})).slice(0,32)}`;
    if(block.phase!=='active')throw new Error('canary_safety_stop_invalid');
    const stoppedAt=input.now??new Date();block.phase='terminal_unreported';block.terminal_reason='safety_failure';block.terminal_kind=null;block.terminal_at=stoppedAt.toISOString();block.stop_receipt_id=receiptId;
    block.latches=ECPE_PILOT_LANES.filter(lane=>activations[lane].activation==='enforce').map(lane=>({latch_id:`latch-${digest(stable({receipt_id:receiptId,participant:'portfolioops',lane,lineage:activations[lane].profile_lineage_hash})).slice(0,32)}`,participant:'portfolioops',lane,profile_lineage_hash:activations[lane].profile_lineage_hash,execution:'legacy',stop_receipt_id:receiptId,superseded:false}));
    block.safety_stop_event={...cause,stop_receipt_id:receiptId,event_hash:digest(`recording.milestone_stop\0${stable({block_id:block.block_id,...cause,stop_receipt_id:receiptId,latches:block.latches})}`)};
    block.revision=blockRevision(block);writeStore(input.stateRoot,store.blocks);
    return{result:'stopped' as const,block_id:block.block_id,phase:block.phase,terminal_reason:block.terminal_reason,stop_receipt_id:receiptId,latch_ids:block.latches.map(item=>item.latch_id)};
    }finally{resolved?.release?.()}
  });
}
export function inspectSafetyLatch(input:{stateRoot:string;participant:'portfolioops';lane:typeof ECPE_PILOT_LANES[number]}){const matches=readStore(input.stateRoot).blocks.flatMap(block=>(block.latches??[]).map(latch=>({block,latch}))).filter(item=>item.latch.participant===input.participant&&item.latch.lane===input.lane&&!item.latch.superseded);if(matches.length>1)throw new Error('safety_latch_ambiguous');if(!matches.length)return{result:'not_applicable',participant:input.participant,lane:input.lane,latch_id:null,execution:'legacy',superseded:false,cause_comparison:null};const{block,latch}=matches[0];return{result:'latched',participant:latch.participant,lane:latch.lane,latch_id:latch.latch_id,execution:'legacy',profile_lineage_hash:latch.profile_lineage_hash,source_block_id:block.block_id,stop_receipt_id:latch.stop_receipt_id,superseded:false,cause_comparison:block.safety_stop_event?.cause_lane===input.lane?structuredClone(block.safety_stop_event.comparison):null}}
export function milestoneNextProducer(block: DurableMilestoneBlock): string { if (!block.slot) return block.phase==='terminal_unreported'?'milestone_block_inspect_for_partial':'pilot_evaluation_preflight';const harness=block.slot.positions.find(position=>position.participant==='harness-governance');if(block.phase==='terminal_unreported'){if(block.terminal_reason==='aborted'&&harness?.producer_claim_id&&!hasHarnessVerificationCleanupAck(block)&&!(block.terminal_resource_handoffs??[]).length)return'verification_terminal_resource_handoff';if((harness?.verification_resource_handle||(block.terminal_resource_handoffs??[]).length)&&!hasHarnessVerificationCleanupAck(block))return'verification_lineage_finalize';return block.terminal_reason?'milestone_block_inspect_for_partial':'milestone_status_prepare'}if(['closing_final','recording_pending'].includes(block.phase))return'recording_binding_inspect';if(block.phase!=='closing_evaluation')return'none'; const unresolved = block.slot.positions.find((position) => !['attached', 'terminalized'].includes(position.state)); if (unresolved?.participant === 'portfolioops') return 'milestone_participant_verify'; if (unresolved?.participant === 'cdo-os') return 'candidate_preview_check'; if (unresolved?.participant === 'harness-governance') return unresolved.state==='retryable_ambiguous'?'verification_workspace_run':'verification_workspace_prepare';if(harness?.verification_resource_handle&&!hasHarnessVerificationCleanupAck(block))return'verification_lineage_finalize'; return block.slot.state === 'complete' || block.slot.state === 'partial' ? 'milestone_status_prepare' : 'pilot_evaluation_build'; }
